import React, { useState, useEffect, useRef } from 'react';
import './Login.css';
import io from 'socket.io-client';

const Login = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSignup, setIsSignup] = useState(false);
  const [error, setError] = useState('');
  const [users, setUsers] = useState([]);
  const socketRef = useRef(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!username.trim() || !password.trim()) return;
    setIsLoading(true);
    const endpoint = isSignup ? '/signup' : '/login';
    try {
      const res = await fetch(`http://localhost:5000${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: username.trim(), password: password.trim() })
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error || 'Authentication failed');
        setIsLoading(false);
        return;
      }
      onLogin(username.trim());
      window._password = password.trim();
    } catch (err) {
      setError('Network error');
      setIsLoading(false);
    }
  };

  useEffect(() => {
    const socket = io('http://localhost:5000');
    socketRef.current = socket;

    if (username && window._password) {
      socket.emit('login', { username, password: window._password });
    }

    socket.on('chatHistory', (history) => setUsers(history));
    socket.on('userList', (userList) => setUsers(userList.filter(u => u.username !== username)));
    socket.on('userTyping', (data) => {
      setUsers(prev => {
        const newUsers = new Map(prev.map(u => [u.socketId, u]));
        if (data.isTyping) {
          newUsers.set(data.socketId, { ...data, username: data.username || 'Someone' });
        } else {
          newUsers.delete(data.socketId);
        }
        return Array.from(newUsers.values());
      });
    });
    socket.on('privateMessages', (msgs) => setUsers(msgs));
    socket.on('message', (message) => {
      if (
        message.type === 'user' &&
        ((message.sender === username && message.recipient === selectedUser?.username) ||
         (message.sender === selectedUser?.username && message.recipient === username))
      ) {
        setUsers(prev => [...prev, message]);
      }
    });

    return () => {
      socket.disconnect();
      socketRef.current = null;
    };
  }, [username, selectedUser]);

  useEffect(() => {
    fetch('http://localhost:5000/all-users')
      .then(res => res.json())
      .then(data => setUsers(data.filter(u => u.username !== username)))
      .catch(err => console.error('Failed to fetch users:', err));
  }, [username]);

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header">
          <h1>ChatApp</h1>
          <p>{isSignup ? 'Create an account' : 'Join the conversation in real-time'}</p>
        </div>
        <form onSubmit={handleSubmit} className="login-form">
          <div className="input-group">
            <label htmlFor="username">Username</label>
            <input
              type="text"
              id="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Enter your username"
              required
              disabled={isLoading}
              className="username-input"
            />
          </div>
          <div className="input-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              required
              disabled={isLoading}
              className="username-input"
            />
          </div>
          {error && <div className="error-message">{error}</div>}
          <button
            type="submit"
            className="login-button"
            disabled={!username.trim() || !password.trim() || isLoading}
          >
            {isLoading ? (isSignup ? 'Signing up...' : 'Logging in...') : (isSignup ? 'Sign Up' : 'Login')}
          </button>
        </form>
        <div className="login-footer">
          <p>
            {isSignup ? 'Already have an account?' : "Don't have an account?"}
            <button
              type="button"
              className="toggle-button"
              onClick={() => { setIsSignup(!isSignup); setError(''); }}
              disabled={isLoading}
            >
              {isSignup ? 'Login' : 'Sign Up'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;
